/* European AQI, CAMS ENSEMBLE via Open-Meteo. Model data, never indoor sensors. */
(function(root){'use strict';
function describe(value){if(!Number.isFinite(value)||value<0)return {label:'Indisponible',position:0};var limits=[20,40,60,80,100],labels=['Bonne','Correcte','Moyenne','Dégradée','Mauvaise','Très mauvaise'],index=limits.findIndex(function(n){return value<=n;});return {label:labels[index<0?5:index],position:Math.min(100,value/120*100)};}
async function load(city,fetcher){if(!city||!Number.isFinite(city.latitude)||!Number.isFinite(city.longitude))throw Error('Ville manquante.');var control=new AbortController(),timeout=setTimeout(function(){control.abort();},12000);try{var r=await (fetcher||fetch)('https://air-quality-api.open-meteo.com/v1/air-quality?'+new URLSearchParams({latitude:city.latitude,longitude:city.longitude,current:'european_aqi,uv_index',timezone:'Europe/Zurich'}),{signal:control.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)throw Error('Qualité de l’air indisponible.');var data=await r.json(),current=data.current;if(!current||!Number.isFinite(current.european_aqi)||current.european_aqi<0)throw Error('Relevé de qualité de l’air indisponible.');return {aqi:current.european_aqi,uv:Number.isFinite(current.uv_index)?current.uv_index:null,time:current.time,updated:Date.now(),latitude:city.latitude,longitude:city.longitude};}finally{clearTimeout(timeout);}}
root.HubAir={load:load,describe:describe};
}(typeof window==='undefined'?globalThis:window));
